def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Repeating background/zero pattern gives the tile period.
    def period(lines):
        for p in range(2, 10):
            if len(lines) > p * 2:
                matches = sum(lines[i] == lines[i % p] for i in range(len(lines)))
                if matches / len(lines) > 0.7:
                    return p
        return 1

    row_period = period([tuple(row) for row in grid])
    col_period = period([tuple(grid[r][c] for r in range(h)) for c in range(w)])

    # Infer periods from the recurring zero separator lines when exact row/column
    # matching is disrupted by marker colors.
    zero_rows = [r for r, row in enumerate(grid) if row.count(0) >= w - 2]
    zero_cols = [c for c in range(w) if sum(grid[r][c] == 0 for r in range(h)) >= h - 2]
    if len(zero_rows) > 1:
        row_period = Counter(b-a for a, b in zip(zero_rows, zero_rows[1:])).most_common(1)[0][0]
    if len(zero_cols) > 1:
        col_period = Counter(b-a for a, b in zip(zero_cols, zero_cols[1:])).most_common(1)[0][0]

    # Markers on separator lines encode the compact output; all other cells
    # represent the repeated background.
    out = [[background for _ in range((w + col_period - 1) // col_period)]
           for _ in range((h + row_period - 1) // row_period)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != background and v != 0:
                i, j = r // row_period, c // col_period
                if i < len(out) and j < len(out[0]):
                    out[i][j] = v
    return out
