def transform(grid):
    h, w = len(grid), len(grid[0])
    # Colored cells on the zero separator lines are the encoded output.
    # Read only the marker-bearing separator lines, in their grid order.
    marked_rows = [
        r for r in range(h)
        if sum(v != 0 for v in grid[r]) <= 6 and any(v not in (0, 5) for v in grid[r])
    ]
    marked_cols = [
        c for c in range(w)
        if sum(grid[r][c] != 0 for r in range(h)) <= 6
    ]

    # Each output cell corresponds to one repeating 3x3 background tile.
    # In these patterns separators occur every four rows / three columns.
    out = []
    for r in marked_rows:
        row = []
        for c in marked_cols:
            v = grid[r][c]
            row.append(v if v != 0 else 5)
        if row:
            out.append(row)

    # Remove separator lines that only border the patterned area.
    if len(out) > 2:
        out = out[1:-1]
    if out and len(out[0]) > 2:
        out = [row[1:-1] for row in out]
    return out
